c.STDIO:
#include <stdio.h>

int main(void) {
    long long n, total = 0;
    scanf("%lld", &n);
    if (n > 15) {
        long long end = n < 60 ? n : 60;
        total += (end - 15) * 2;
    }
    if (n > 60) {
        total += n - 60;
    }
    printf("%lld\n", total);
    return 0;
}

